'use strict';
const TeamHub=(()=>{
 const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const labels={dashboard:'看板',games:'比赛',trainings:'训练',players:'队员'};
 const today=()=>{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');};
 const stateLabel=t=>({planned:'计划中',completed:'已完成',cancelled:'已取消'}[t.status]||'未设置');
 const avatar=(p,size='')=>'<span class="team-avatar '+size+'">'+(p?.avatar?'<img src="'+esc(p.avatar)+'" alt="'+esc(p.name)+'的头像" width="64" height="64" decoding="async">':esc(p?.name?.slice(0,1)||'人'))+'</span>';
 function init(d){
  let section='dashboard',scope='personal',practice=false,averages=false,lastId=null,trainingEdit=null,profileSaving=false,image=null,photoURL=null,zoom=1,offset={x:0,y:0},drag=null;
  const state=d.getState;
  function navigate(next,updateURL=true){section=labels[next]?next:'dashboard';$$('[data-team-pane]').forEach(el=>el.hidden=el.dataset.teamPane!==section);$$('[data-team-tab]').forEach(el=>{if(el.dataset.teamTab===section)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});if(updateURL&&document.body.classList.contains('stats-mode'))window.history.replaceState(window.history.state,'',section==='dashboard'?'#team':'#team/'+section);render();}
  function renderHeader(){const {me}=state(),admin=d.canEdit(),button=$('#stats-login');$('#stats-unlock').innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/></svg><span>'+(admin?'管理中':'开启编辑')+'</span>';$('#stats-unlock').hidden=false;$('#stats-unlock').setAttribute('aria-label',admin?'退出管理模式':'开启编辑');$('#stats-unlock').setAttribute('aria-pressed',String(admin));$('#stats-unlock').title=admin?'退出管理模式':'开启编辑';button.hidden=false;button.innerHTML=avatar(me,'team-avatar-small')+'<span>'+esc(me?.name||'队员登录')+'</span>';button.setAttribute('aria-label',me?'编辑个人资料：'+me.name:'队员登录');button.setAttribute('aria-controls','team-profile-dialog');button.setAttribute('aria-haspopup','dialog');$('#team-user-name').textContent=me?'#'+me.number+' '+me.name:'';if(!me){$('#team-user-menu').hidden=true;button.setAttribute('aria-expanded','false');}}
  function card(label,value,note=''){return '<article class="team-metric"><span>'+label+'</span><strong>'+value+'</strong>'+(note?'<small>'+note+'</small>':'')+'</article>';}
  function gameButton(g){return '<button type="button" class="team-feed-row" data-stats-game="'+esc(g.id)+'"><span class="team-feed-icon">◉</span><span><strong>'+esc(g.name)+'</strong><small>'+esc(g.heldOn||'日期未设置')+' · '+(g.status==='live'?'进行中':'已结束')+(g.opponent?' · vs '+esc(g.opponent):'')+'</small></span><span>›</span></button>';}
  function trainingButton(t,personal=false){const p=state().me;return '<button type="button" class="team-feed-row'+(state().notifications?.trainings?.[t.id]?' has-alert':'')+'" data-training-card="'+esc(t.id)+'"><span class="team-feed-icon">◷</span><span><strong>'+esc(t.name)+'</strong><small>'+esc(t.heldOn)+' · '+stateLabel(t)+(personal&&p&&TeamMetrics.eligible(t,p,today())?' · '+(t.attendees.includes(p.id)?'已出勤':'未出勤'):'')+'</small></span><span>›</span></button>';}
  function panel(title,body,more=''){return '<section class="team-card"><div class="team-card-heading"><h2>'+title+'</h2>'+more+'</div>'+body+'</section>';}
  const empty=text=>'<p class="team-empty">'+text+'</p>';
  function render(){
   const {data,me,loaded,error}=state();if(lastId!==me?.id){scope=me?'personal':'team';lastId=me?.id;if($('#team-profile-dialog').open)$('#team-profile-dialog').close();}
   renderHeader();$('[data-team-tab="trainings"]').classList.toggle('has-alert',!!state().notifications?.unread);$('#team-scope').hidden=!me||section!=='dashboard';$$('[data-team-scope]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.teamScope===scope)));
   $('#team-page-title').textContent=section==='dashboard'?(me&&scope==='personal'?'我的看板':'全队总览'):labels[section];
   $('#stats-new-game').hidden=!d.canEdit()||section!=='games';$('#stats-players-btn').hidden=!d.canEdit()||section!=='players';$('#trainings-new').hidden=!d.canEdit()||section!=='trainings';$('#team-page-actions').hidden=!d.canEdit()||section==='dashboard';
   const roster=$('#team-roster-grid'),rosterLeft=roster.scrollLeft;roster.dataset.rows=data.players.length>1?'2':'1';roster.innerHTML=data.players.map(p=>{const a=TeamMetrics.attendance(data.trainings,p,today());return '<article class="team-player-card">'+avatar(p)+'<div><strong>'+esc(p.name)+'</strong><small>#'+p.number+' · '+(p.gender==='female'?'女':p.gender==='male'?'男':'未设置')+'</small><small>训练 '+a.present+'/'+a.total+' · '+(a.rate===null?'暂无出勤率':a.rate+'%')+'</small></div>'+(d.canEdit()?'<span class="team-credential '+(p.loginReady?'':'pending')+'">'+(p.loginReady?'口令已设置':'待设置口令')+'</span>':'')+'</article>';}).join('')||empty('名单为空，管理员可以添加队员。');roster.scrollLeft=rosterLeft;syncRosterHint();
   if(loaded&&section!=='dashboard')$('#stats-meta').textContent=section==='players'?data.players.length+' 名队员':section==='games'?data.games.length+' 场正式比赛':data.trainings.length+' 次训练';
   if(!loaded){$('#team-dashboard').innerHTML=panel(error?'暂时无法同步':'正在加载',empty(error?esc(error):'正在连接全队数据…'));return;}
   const moreOpen=$('.team-more-metrics')?.open;let html='';
   if(me&&scope==='personal'){
    const m=TeamMetrics.personal(data,me,today(),practice),t=m.totals,a=m.attendance,divisor=averages?m.finished.length:1;
    const number=value=>divisor?(averages?(value/divisor).toFixed(1):String(value)):'—';
    html='';
    html+='<div class="team-data-controls"><label class="sr-only" for="team-game-source">统计范围</label><select id="team-game-source"><option value="formal"'+(!practice?' selected':'')+'>正式比赛</option><option value="practice"'+(practice?' selected':'')+'>训练赛</option></select><div class="team-scope"><button type="button" data-team-average="total" aria-pressed="'+!averages+'">总计</button><button type="button" data-team-average="average" aria-pressed="'+averages+'">场均</button></div></div>';
    html+='<div class="team-metrics">'+card('参赛',m.finished.length,'已结束 · 有本人记录')+card('得分',number(t.goals))+card('助攻',number(t.assists))+card('防守成功',number(t.steals))+'</div>';
    html+='<details class="team-more-metrics"><summary>传盘、失误与上场数据</summary><div class="team-metrics">'+card('传盘完成',number(t.passes))+card('失误',number(t.turnovers))+card('上场分数',number(t.points))+card('进攻 / 防守开',number(t.oPoints)+' / '+number(t.dPoints))+'</div></details>';
    const attendance=panel('我的训练考勤','<div class="team-attendance-score"><strong>'+(a.rate===null?'—':a.rate+'%')+'</strong><span>出勤 '+a.present+' / '+a.total+' 次</span></div><p class="team-caption">仅计已完成、日期已到的训练'+(me.joinedOn?' · 入队日期 '+esc(me.joinedOn)+'；入队前已登记的出勤也计入':'')+'</p>'+(a.list.slice(0,4).map(t=>trainingButton(t,true)).join('')||empty('还没有符合统计条件的训练。')),'<button type="button" class="team-link" data-team-goto="trainings">全部训练 ↗</button>');
    const candidates=[...m.games.filter(g=>g.status==='finished').map(g=>({kind:'game',entry:g})),...a.list.filter(t=>t.attendees.includes(me.id)).map(t=>({kind:'training',entry:t}))];
    const pending=candidates.filter(x=>!x.entry.comments.some(c=>c.player===me.id&&!c.deleted));
    const reviews=panel('我的心得','<div class="team-pending-note">'+(pending.length?pending.length+' 场待记录，趁记忆还新鲜。':'参加过的比赛和训练，会在这里等你记录。')+'</div>'+pending.slice(0,4).map(x=>'<button type="button" class="team-feed-row" data-team-review="'+x.kind+'" data-entry="'+esc(x.entry.id)+'"><span class="team-feed-icon">✎</span><span><strong>'+esc(x.entry.name)+'</strong><small>'+(x.kind==='game'?'比赛心得':'训练心得')+' · 待撰写</small></span><span>›</span></button>').join('')+candidates.filter(x=>x.entry.comments.some(c=>c.player===me.id&&!c.deleted)).slice(0,3).map(x=>{const c=x.entry.comments.find(c=>c.player===me.id&&!c.deleted);return '<button type="button" class="team-written-review" data-team-review="'+x.kind+'" data-entry="'+esc(x.entry.id)+'"><strong>'+esc(x.entry.name)+' <small>已参与 · 查看讨论 ↗</small></strong><p>'+esc(c.text)+'</p></button>';}).join(''));
    html+='<div class="team-dashboard-grid">'+attendance+reviews+'</div>';
    html+=panel('我的近期比赛',m.games.slice(0,4).map(gameButton).join('')||empty('还没有本人的参赛记录。'));
   }else{
    const finished=data.games.filter(g=>g.status==='finished'),completed=data.trainings.filter(t=>TeamMetrics.eligible(t,null,today())),goals=finished.reduce((n,g)=>n+g.events.filter(e=>e.kind==='goal').length,0);
    html='<div class="team-metrics">'+card('队员',data.players.length,'一起奔跑的伙伴')+card('正式比赛',finished.length,'已结束的比赛')+card('训练',completed.length,'已完成的训练')+card('得分',goals,'正式比赛累计')+'</div>';
    if(d.canEdit())html+='<div class="team-admin-note"><span>管理模式已开启</span><button type="button" class="quiet-btn" data-team-create="game">＋ 比赛</button><button type="button" class="quiet-btn" data-team-create="training">＋ 训练</button><button type="button" class="quiet-btn" data-team-create="player">＋ 队员</button></div>';
    const upcoming=data.trainings.filter(t=>t.status==='planned').sort((a,b)=>a.heldOn.localeCompare(b.heldOn));
    html+='<div class="team-dashboard-grid">'+panel('训练安排',upcoming.slice(0,3).map(t=>trainingButton(t)).join('')||empty('暂无待进行的训练。'),'<button type="button" class="team-link" data-team-goto="trainings">全部训练 ↗</button>')+panel('近期比赛',TeamMetrics.gamesByDate(data.games).slice(0,3).map(gameButton).join('')||empty('暂无比赛记录。'),'<button type="button" class="team-link" data-team-goto="games">全部比赛 ↗</button>')+'</div>';
    html+=panel('一起训练',completed.slice().sort((a,b)=>b.heldOn.localeCompare(a.heldOn)).slice(0,3).map(t=>trainingButton(t)).join('')||empty('完成训练后，这里会留下全队的训练记录。'),'<button type="button" class="team-link" data-team-goto="players">队员与全队统计 ↗</button>');
   }
   $('#team-dashboard').innerHTML=html;if(moreOpen&&$('.team-more-metrics'))$('.team-more-metrics').open=true;
  }
  function openProfile(){if(!state().me){d.login();return;}$('#team-user-menu').hidden=true;$('#team-password-form').reset();$('#team-profile-status').textContent='';$('#team-profile-current').innerHTML=avatar(state().me,'team-avatar-large');$('#team-profile-dialog').showModal();$('#team-profile-title').focus({preventScroll:true});}
  function releasePhoto(){image?.close?.();image=null;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=null;$('#team-avatar-editor').hidden=true;$('#team-avatar-file').value='';}
  function draw(){if(!image)return;const canvas=$('#team-avatar-canvas'),ctx=canvas.getContext('2d'),base=Math.max(256/image.width,256/image.height)*zoom,w=image.width*base,h=image.height*base;offset.x=Math.max(-(w-256)/2,Math.min((w-256)/2,offset.x));offset.y=Math.max(-(h-256)/2,Math.min((h-256)/2,offset.y));ctx.fillStyle='#fff';ctx.fillRect(0,0,256,256);ctx.drawImage(image,(256-w)/2+offset.x,(256-h)/2+offset.y,w,h);}
  async function loadPhoto(file){releasePhoto();if(!file)return;if(!file.type.startsWith('image/')||file.size>30*1024*1024){d.toast('请选择 30MB 以内的照片。');return;}try{photoURL=URL.createObjectURL(file);const img=new Image();img.src=photoURL;await img.decode();if(!img.width||!img.height)throw new Error();image=img;zoom=1;offset={x:0,y:0};$('#team-avatar-zoom').value='1';$('#team-avatar-status').textContent='';$('#team-avatar-editor').hidden=false;draw();}catch{releasePhoto();d.toast('无法读取照片，请转为 JPG、PNG 或 WebP 后重试。');}}
  async function savePhoto(){if(!image||profileSaving)return;profileSaving=true;$('#team-avatar-save').disabled=true;$('#team-avatar-status').textContent='正在压缩并保存…';try{const blob=await new Promise(resolve=>$('#team-avatar-canvas').toBlob(resolve,'image/jpeg',.82));if(!blob)throw new Error('无法压缩照片。');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob);});const result=await d.api('stats/me',{method:'PUT',body:JSON.stringify({avatar:encoded})});await d.refresh();$('#team-profile-current').innerHTML=avatar(result.player,'team-avatar-large');releasePhoto();d.toast('头像已压缩并保存到服务器。');}catch(error){$('#team-avatar-status').textContent=error.message;}finally{profileSaving=false;$('#team-avatar-save').disabled=false;}}
  function openTrainingInfo(t=null){if(!d.canEdit())return;document.querySelectorAll('.more-menu').forEach(menu=>menu.open=false);trainingEdit=t;$('#team-training-info-title').textContent=t?'训练信息':'新建训练';$('#team-training-name').value=t?.name||today()+' 训练';$('#team-training-date').value=t?.heldOn||today();$('#team-training-status').value=t?.status||'planned';$('#team-training-info-dialog').showModal();$('#team-training-info-title').focus({preventScroll:true});}
  function syncRosterHint(){const roster=$('#team-roster-grid');$('#team-roster-hint').hidden=roster.scrollWidth<=roster.clientWidth+1;}
  if(window.ResizeObserver)new ResizeObserver(syncRosterHint).observe($('#team-roster-grid'));else window.addEventListener('resize',syncRosterHint);
  $('#team-roster-grid').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const roster=event.currentTarget,card=roster.querySelector('.team-player-card'),step=(card?.getBoundingClientRect().width||240)+(parseFloat(getComputedStyle(roster).columnGap)||0),left=event.key==='Home'?0:event.key==='End'?roster.scrollWidth:roster.scrollLeft+(event.key==='ArrowRight'?step:-step);roster.scrollTo({left,behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});});
  $('#stats-unlock').onclick=d.toggleEdit;
  $('#stats-login').onclick=openProfile;
  $('#team-my-board').onclick=()=>{scope='personal';$('#team-user-menu').hidden=true;d.openTeam();navigate('dashboard');};
  $('#team-profile-open').onclick=openProfile;$('#team-switch-player').onclick=()=>{if(profileSaving)return;$('#team-user-menu').hidden=true;$('#team-profile-dialog').close();d.login();};
  const logout=$('#stats-logout').onclick;$('#stats-logout').onclick=()=>{if(profileSaving)return;$('#team-profile-dialog').close();logout();};
  document.addEventListener('click',event=>{if(!event.target.closest('.team-user')){$('#team-user-menu').hidden=true;$('#stats-login').setAttribute('aria-expanded','false');}const tab=event.target.closest('[data-team-tab],[data-team-goto]');if(tab){navigate(tab.dataset.teamTab||tab.dataset.teamGoto);return;}const s=event.target.closest('[data-team-scope]');if(s){scope=s.dataset.teamScope;render();return;}const a=event.target.closest('[data-team-average]');if(a){averages=a.dataset.teamAverage==='average';render();return;}if(event.target.closest('[data-team-profile]'))openProfile();const create=event.target.closest('[data-team-create]');if(create){({game:()=>$('#stats-new-game').click(),training:()=>d.requestEdit(()=>openTrainingInfo()),player:()=>$('#stats-players-btn').click()})[create.dataset.teamCreate]();}const review=event.target.closest('[data-team-review]');if(review){if(review.dataset.teamReview==='game')d.openReview(review.dataset.entry);else d.openTrainingReview(review.dataset.entry);} });
  document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('#team-user-menu').hidden=true;$('#stats-login').setAttribute('aria-expanded','false');}});
  $('#team-dashboard').addEventListener('change',event=>{if(event.target.id==='team-game-source'){practice=event.target.value==='practice';render();}});
  $$('[data-team-close]').forEach(b=>b.onclick=()=>{if(b.dataset.teamClose==='team-profile-dialog'&&profileSaving){d.toast('头像正在保存，请稍候。');return;}$('#'+b.dataset.teamClose).close();});
  $('#team-avatar-file').onchange=event=>loadPhoto(event.target.files[0]);$('#team-avatar-zoom').oninput=event=>{zoom=Number(event.target.value);draw();};$('#team-avatar-cancel').onclick=releasePhoto;$('#team-avatar-save').onclick=savePhoto;
  const canvas=$('#team-avatar-canvas');canvas.addEventListener('pointerdown',event=>{if(!image)return;drag={x:event.clientX,y:event.clientY,ox:offset.x,oy:offset.y,id:event.pointerId};canvas.setPointerCapture(event.pointerId);});canvas.addEventListener('pointermove',event=>{if(!drag||event.pointerId!==drag.id)return;const scale=256/canvas.getBoundingClientRect().width;offset={x:drag.ox+(event.clientX-drag.x)*scale,y:drag.oy+(event.clientY-drag.y)*scale};draw();});['pointerup','pointercancel','lostpointercapture'].forEach(type=>canvas.addEventListener(type,()=>drag=null));
  $('#team-profile-dialog').addEventListener('cancel',event=>{if(profileSaving){event.preventDefault();d.toast('头像正在保存，请稍候。');}});$('#team-profile-dialog').addEventListener('close',()=>{releasePhoto();$('#team-password-form').reset();});
  $('#team-password-form').onsubmit=async event=>{event.preventDefault();if($('#team-new-password').value!==$('#team-confirm-password').value){$('#team-profile-status').textContent='两次新口令不一致。';return;}const button=$('#team-password-form button');button.disabled=true;try{await d.api('stats/me',{method:'PUT',body:JSON.stringify({password:$('#team-new-password').value,currentPassword:$('#team-current-password').value})});$('#team-profile-dialog').close();await d.refresh();d.login();d.toast('个人口令已更新，请重新登录。');}catch(error){$('#team-profile-status').textContent=error.message;}finally{button.disabled=false;}};
  $('#trainings-new').onclick=()=>openTrainingInfo();$('#team-training-edit').onclick=$('#team-training-date-edit').onclick=()=>openTrainingInfo(d.currentTraining());
  $('#team-training-info-form').onsubmit=async event=>{event.preventDefault();const button=$('#team-training-info-form button[type="submit"]');button.disabled=true;try{const body={name:$('#team-training-name').value.trim(),heldOn:$('#team-training-date').value,status:$('#team-training-status').value};const result=await d.api('stats/trainings'+(trainingEdit?'/'+trainingEdit.id:''),{method:trainingEdit?'PUT':'POST',body:JSON.stringify(body)});$('#team-training-info-dialog').close();await d.refresh();if(!trainingEdit)d.openTraining(result.training.id);d.toast('训练信息已保存。');}catch(error){d.toast(error.message);}finally{button.disabled=false;}};
  return{render,renderHeader,navigate,openProfile,afterLogin:()=>{scope='personal';d.openTeam();navigate('dashboard');}};
 }
 return{init};
})();
